tasks.setup:
let count = 0;
function safe(cols, row, col) {
  for (let r = 0; r < row; r++) {
    const c = cols[r];
    if (c === col) return false;
    if (Math.abs(c - col) === Math.abs(r - row)) return false;
  }
  return true;
}
function solve(n, row = 0, cols = []) {
  if (row === n) { count++; return; }
  for (let col = 0; col < n; col++) {
    if (safe(cols, row, col)) {   // prune before recursing
      cols.push(col);             // choose
      solve(n, row + 1, cols);    // explore
      cols.pop();                 // undo
    }
  }
}
solve(8);
console.log('8-queens solutions: ' + count);
